import {CardSearch} from './card-search.mjs';
import {indexCards,newDeck,validateDeck,addCard,importText,deckText,deckStats,DeckStore,zones,zoneLabels} from './deck-model.mjs';
import {setProxyDeck} from './proxy-printer.mjs?v=3';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const download=(name,data,type)=>{const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);};
let index,store=new DeckStore(),trash=false,visual=false,undo=[],search='',zone='spell';
export async function mountDeckBuilder(root,cards,lang,id){
 const t=(de,en)=>lang==='en'?en:de,zname=z=>zoneLabels[z][lang==='en'?1:0],route=id=>`#/${lang}/decks${id?'/'+id:''}`, $=s=>root.querySelector(s);
 root.innerHTML=`<p>${t('Decks werden geladen …','Loading decks …')}</p>`;
 try{if(!index){const response=await fetch('data/card-identities.json');if(!response.ok)throw Error('Card identities unavailable');index=indexCards(cards,await response.json());}if(!location.hash.includes('/decks'))return;render();}catch(e){root.innerHTML=`<h1>${t('Decks nicht verfügbar','Decks unavailable')}</h1><p>${esc(e.message)}</p>`;}
 function message(s){$('#deck-message').textContent=s;}
 function list(){return store.read();}
 function current(){return list().find(d=>d.id===id);}
 function save(d,remember=true){try{validateDeck(d,index);if(remember){undo.push(structuredClone(current()));if(undo.length>40)undo.shift();}store.save(d,index);render();return true;}catch(e){message(t('Speichern fehlgeschlagen: ','Save failed: ')+e.message);return false;}}
 function button(label,action){return `<button class="pill" data-action="${action}">${label}</button>`;}
 function render(){
  const deck=current();root.innerHTML=`<div class="deck-heading"><div><div class="eyebrow">BLUTBANK / ${t('DECKBUILDER','DECK BUILDER')}</div><h1>${deck?esc(deck.name):t('Meine Decks','My decks')}</h1></div><a class="pill" href="#/${lang}/account">${t('Konto & Online-Decks','Account & online decks')}</a></div><p class="muted">${t('Automatisch in diesem Browser gespeichert. JSON-Export als Sicherung verwenden.','Automatically saved in this browser. Use JSON export to keep a backup.')}</p><p id="deck-message" role="status" aria-live="polite"></p>`;
  if(id&&!deck){root.innerHTML+=`<p>${t('Deck nicht gefunden.','Deck not found.')}</p><a href="${route('')}">${t('Meine Decks','My decks')}</a>`;return;}
  if(!deck){renderList();return;}
  if(deck.trashed){root.innerHTML+=`<p>${t('Dieses Deck liegt im Papierkorb.','This deck is in the trash.')}</p>${button(t('Wiederherstellen','Restore'),'restore')}`;bind({restore:()=>save({...deck,trashed:false})});return;}
  const stats=deckStats(deck,index);
  root.innerHTML+=`<div class="deck-toolbar"><a class="pill" href="${route('')}">← ${t('Meine Decks','My decks')}</a>${button(t('Liste / Bilder','List / images'),'visual')}${button(t('Rückgängig','Undo'),'undo')}${button(t('Kopie erstellen','Make a copy'),'copy')}${button(t('Text exportieren','Export text'),'text')}${button('JSON','json')}${button(t('Proxies drucken','Print proxies'),'proxy')}${button(t('Online speichern','Save online'),'cloud')}</div>
  <div class="deck-workspace"><aside class="deck-details"><label>${t('Deckname','Deck name')}<input id="deck-name" maxlength="120" value="${esc(deck.name)}"></label><label>${t('Beschreibung','Description')}<textarea id="deck-description" rows="3" maxlength="5000">${esc(deck.description)}</textarea></label><strong>${stats.total} ${t('Karten','cards')}</strong><dl>${zones.map(z=>`<div><dt>${zname(z)}</dt><dd>${stats.counts[z]}</dd></div>`).join('')}</dl><h3>${t('ASP-Verteilung','ASP distribution')}</h3><div class="deck-curve">${Object.entries(stats.curve).sort((a,b)=>Number(a[0])-Number(b[0])).map(([n,q])=>`<div><span>${esc(n)} ASP</span><meter min="0" max="${Math.max(...Object.values(stats.curve))}" value="${q}"></meter><b>${q}</b></div>`).join('')}</div><p class="muted">${stats.unknown} ${t('ohne erfasste ASP-Kosten','without recorded ASP cost')}</p><details><summary>${t('Deckbau-Hinweise','Deck building notes')}</summary><p>${t('Vorläufige Prüfung auf Basis der erfassten Kartendaten; keine vollständige Turnierlegalitätsprüfung.','Preliminary checks based on recorded card data; not a complete tournament legality check.')}</p>${stats.issues.map(s=>`<p>${esc(s)}</p>`).join('')}<a href="#/${lang}/rules/2.4">${t('Deckbauregeln lesen','Read deck building rules')}</a></details>${button(t('In Papierkorb verschieben','Move to trash'),'trash')}</aside>
  <section class="deck-cards"><h2>${t('Deckliste','Deck list')}</h2>${zones.map(z=>renderZone(deck,z)).join('')}<details class="deck-import"><summary>${t('Kartenliste importieren','Import card list')}</summary><p>${t('Eine Karte pro Zeile, z. B. 3x Oracle. Wird zum Deck hinzugefügt. Pool-Zuordnung anschließend prüfen.','One card per line, e.g. 3x Oracle. Adds to the deck. Check pool assignments afterwards.')}</p><textarea id="deck-import" rows="5" aria-label="${t('Kartenliste importieren','Import card list')}"></textarea>${button(t('Liste hinzufügen','Add list'),'import')}</details></section>
  <section class="deck-search"><h2>${t('Karten hinzufügen','Add cards')}</h2><input id="deck-search" aria-label="${t('Karten durchsuchen','Search cards')}" placeholder="${t('Name, Keyword, asp<=3 …','Name, keyword, asp<=3 …')}" value="${esc(search)}"><label>${t('Hinzufügen zu','Add to')}<select id="deck-zone">${zones.map(z=>`<option value="${z}" ${zone===z?'selected':''}>${zname(z)}</option>`).join('')}</select></label><div id="deck-results"></div></section></div>`;
  for(const key of ['name','description']){const input=$('#deck-'+key);input.onfocus=()=>{undo.push(structuredClone(current()));};input.oninput=()=>{const value=key==='name'?input.value.trim():input.value;if(key==='name'&&!value){message(t('Bitte einen Namen eingeben.','Please enter a name.'));return;}try{deck[key]=value;store.save(deck,index);if(key==='name')$('h1').textContent=value;message(t('Gespeichert','Saved'));}catch(e){message(e.message);}};}

  $('#deck-zone').onchange=e=>zone=e.target.value;$('#deck-search').oninput=e=>{search=e.target.value;results();};results();
  root.querySelectorAll('[data-quantity]').forEach(el=>el.onchange=()=>{const d=structuredClone(deck),i=Number(el.dataset.quantity),n=Number(el.value);if(n===0)d.entries.splice(i,1);else d.entries[i].quantity=n;save(d);});
  root.querySelectorAll('[data-version]').forEach(el=>el.onchange=()=>{const d=structuredClone(deck);d.entries[Number(el.dataset.version)].printingId=el.value;save(merge(d));});
  root.querySelectorAll('[data-zone]').forEach(el=>el.onchange=()=>{const d=structuredClone(deck);d.entries[Number(el.dataset.zone)].zone=el.value;save(merge(d));});
  root.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{const d=structuredClone(deck);d.entries.splice(Number(el.dataset.remove),1);save(d);});
  bind({visual:()=>{visual=!visual;render()},undo:()=>{const previous=undo.pop();if(previous?.id===id)save(previous,false);else message(t('Keine Änderung zum Rückgängigmachen.','Nothing to undo.'));},copy:()=>copy(deck),text:()=>download('blutbank-deck.txt',deckText(deck,index),'text/plain'),json:()=>download('blutbank-deck.json',JSON.stringify(deck,null,2),'application/json'),proxy:()=>{setProxyDeck(deck.entries.filter(e=>e.zone!=='maybe').map(e=>({id:e.printingId,quantity:e.quantity})),cards);location.hash=`#/${lang}/proxy`;},trash:()=>{if(save({...deck,trashed:true}))location.hash=route('');},import:()=>{const parsed=importText($('#deck-import').value,index);if(parsed.errors.length){message(t('Nicht importiert. Unbekannte/ungültige Zeilen: ','Not imported. Unknown/invalid lines: ')+parsed.errors.map(e=>`${e.line}: ${e.name}`).join('; '));return;}save(merge({...deck,entries:[...deck.entries,...parsed.entries]}));},cloud:async()=>{try{const {saveOnline}=await import('./deck-online.mjs');await saveOnline(deck);message(t('Online gespeichert.','Saved online.'));}catch(e){message(e.message);}}});
 }
 function merge(d){const map=new Map();for(const e of d.entries){const k=e.printingId+':'+e.zone;if(map.has(k))map.get(k).quantity+=e.quantity;else map.set(k,{...e});}return {...d,entries:[...map.values()]};}
 function renderZone(deck,z){const entries=deck.entries.map((e,i)=>({...e,i})).filter(e=>e.zone===z);return `<section class="deck-section"><h3>${zname(z)} <span>${entries.reduce((n,e)=>n+e.quantity,0)}</span></h3><div class="${visual?'deck-visual':''}">${entries.map(e=>{const g=index.find(g=>g.id===e.cardId),c=g?.variants.find(c=>c.id===e.printingId);return `<article class="deck-entry"><div class="deck-entry-main"><input type="number" min="0" max="300" value="${e.quantity}" data-quantity="${e.i}" aria-label="${esc(g.name)} ${t('Anzahl','quantity')}"><a class="deck-card-name" href="#/${lang}/cards/${c.id}">${esc(g.name)}<img class="deck-hover" src="${esc(c.image)}" alt="${esc(g.name)}" loading="lazy"></a>${button('×','unused').replace('data-action="unused"',`data-remove="${e.i}" aria-label="${t('Entfernen','Remove')} ${esc(g.name)}"`)}</div>${visual?`<img class="deck-card-image" src="${esc(c.image)}" alt="${esc(g.name)}" loading="lazy">`:''}<div class="deck-entry-options"><select data-zone="${e.i}" aria-label="${esc(g.name)} ${t('Bereich','zone')}">${zones.map(z=>`<option value="${z}" ${z===e.zone?'selected':''}>${zname(z)}</option>`).join('')}</select><select data-version="${e.i}" aria-label="${esc(g.name)} ${t('Version','printing')}">${g.variants.map((v,i)=>`<option value="${v.id}" ${v.id===c.id?'selected':''}>${esc(v.set)} · ${esc(v.code||'')} · ${esc(v.variant||i+1)}</option>`).join('')}</select></div></article>`;}).join('')||`<p class="muted">${t('Noch keine Karten','No cards yet')}</p>`}</div></section>`;}
 function results(){const groups=index.filter(g=>g.variants.some(c=>CardSearch.matches(c,{q:search})));$('#deck-results').innerHTML=`<p class="muted">${groups.length} ${t('Treffer','results')}${groups.length>30?' · '+t('erste 30','first 30'):''}</p>${groups.slice(0,30).map(g=>`<div class="deck-result"><a href="#/${lang}/cards/${g.card.id}"><img src="${esc(g.card.image)}" alt="${esc(g.name)}" loading="lazy"></a><div><strong>${esc(g.name)}</strong><small>${esc(g.card.text?.typeLine||'')}</small><button class="pill" data-add="${g.id}" aria-label="${esc(g.name)} ${t('hinzufügen','add')}">+ ${t('Hinzufügen','Add')}</button></div></div>`).join('')}`;root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>save(addCard(current(),index.find(g=>g.id===b.dataset.add),undefined,zone)));}
 function bind(actions){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=actions[b.dataset.action]);}
 function copy(d){const clone={...structuredClone(d),id:crypto.randomUUID(),name:(t('Kopie von ','Copy of ')+d.name).slice(0,120),trashed:false};try{store.save(clone,index);undo=[];location.hash=route(clone.id);}catch(e){message(e.message);}}
 function renderList(){root.innerHTML+=`<div class="deck-toolbar">${button(t('Neues Deck','New deck'),'new')}${button(trash?t('Meine Decks','My decks'):t('Papierkorb','Trash'),'toggle')}<label class="pill">${t('JSON importieren','Import JSON')}<input id="deck-file" type="file" accept="application/json,.json"></label></div><div class="deck-list">${list().filter(d=>!!d.trashed===trash).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(d=>`<article><div><a href="${route(d.id)}"><strong>${esc(d.name)}</strong></a><small>${deckStats(d,index).total} ${t('Karten','cards')} · ${new Date(d.updatedAt).toLocaleDateString(lang)}</small></div><a class="pill" href="${route(d.id)}">${trash?t('Wiederherstellen','Restore'):t('Bearbeiten','Edit')}</a></article>`).join('')||`<p class="empty">${t('Hier sind noch keine Decks.','No decks here yet.')}</p>`}</div>`;bind({new:()=>{const d=newDeck(t('Neues Deck','New deck'));try{store.save(d,index);undo=[];location.hash=route(d.id);}catch(e){message(e.message);}},toggle:()=>{trash=!trash;render();}});$('#deck-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>300000)throw Error(t('Datei zu groß.','File too large.'));const d=validateDeck(JSON.parse(await f.text()),index);copy(d);}catch(error){message(error.message);}};}
}
